cd /filesystem && python3 - <<'EOF'
import openpyxl
for f in ["Reports-Studies/DSR_Ph3_StormDrain_HGL.xlsx"]:
    wb = openpyxl.load_workbook(f)
    wbv = openpyxl.load_workbook(f, data_only=True)
    print("########", f, wb.sheetnames)
    for ws in wb.worksheets:
        wsv = wbv[ws.title]
        print("=== SHEET:", ws.title, ws.dimensions, ws.sheet_state)
        hidden_rows=[r for r,d in ws.row_dimensions.items() if d.hidden]
        hidden_cols=[c for c,d in ws.column_dimensions.items() if d.hidden]
        if hidden_rows or hidden_cols: print("HIDDEN", hidden_rows, hidden_cols)
        for row in ws.iter_rows():
            out=[]
            for c in row:
                if c.value is None: continue
                v=c.value
                cv=wsv[c.coordinate].value
                if isinstance(v,str) and v.startswith('='):
                    out.append(f"{c.coordinate}: {v} -> {cv}")
                else:
                    out.append(f"{c.coordinate}: {v!r}")
                if c.comment: out.append(f"[COMMENT {c.coordinate}: {c.comment.text}]")
            if out: print(" | ".join(out))
EOF

